public static boolean isPriceAttributeEnabled(FormControl _sender)
{
    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        return false;
    }

    PriceDiscAdmTrans priceDiscAdmTrans = _sender.formRun().dataSource('PriceDiscAdmTrans').cursor();
    if (!priceDiscAdmTrans.getPriceDiscAdmName().PriceDiscPriceAttributeEnable)
    {
        return false;
    }

    return true;
}

[FormControlEventHandler(formControlStr(PriceDiscAdm, InventoryDimension_configId), FormControlEventType::Lookup)]
public static void InventoryDimension_configId_OnLookup(FormControl sender, FormControlEventArgs e)
{
    if (!GUPPriceDiscAdmTransFormEventHandler::isPriceAttributeEnabled(sender))
    {
        return;
    }

    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource  = query.addDataSource(tableNum(EcoResConfiguration));
    SysTableLookup          tableLookup = SysTableLookup::newParameters(tablenum(EcoResConfiguration), sender);
    tableLookup.addLookupfield(fieldnum(EcoResConfiguration, Name));
    tableLookup.parmQuery(query);
    tableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    ce.CancelSuperCall();
}

